// chargement-navbar.js
const pageLanguage = document.documentElement.lang;
const navigationFile = pageLanguage.startsWith('en') ? 'navigation_en.html' : 'navigation.html';

async function loadAndInitNavigation() {
    const container = document.getElementById('banner-container');
    if (!container) return;

    try {
        const response = await fetch(navigationFile);
        if (!response.ok) throw new Error('Fichier introuvable');
        const html = await response.text();
        
        container.innerHTML = html;

        const toggleButton = document.getElementById('menu-toggle-button');
        const sidebar = container.querySelector('.fixed-sidebar');

        if (toggleButton && sidebar) {
            toggleButton.addEventListener('click', () => {
                const isMenuOpen = sidebar.classList.toggle('is-open');
                toggleButton.setAttribute('aria-expanded', isMenuOpen);
                toggleButton.textContent = isMenuOpen ? '✕' : '☰';
            });
        }
    } catch (error) {
        container.innerHTML = '<p>Navigation indisponible</p>';
    }
}

document.addEventListener('DOMContentLoaded', loadAndInitNavigation);